INSERT INTO messages (name, city, content, leaf) VALUES
('ريم','طرطوس','صفحتك أجمل من كوب شاي بالنعنع في صيف طرطوس. نظّمت مكتبي بعد نصيحتك وصرت أشتغل أسرع!', '🌿'),
('أحمد','اللاذقية','أرسلت لك أرشيف مكتبتي كله، والحمد لله رجعت ألقى كل ورقة بمكانها. شكرًا shatlet.', '🍃'),
('لينا','دمشق','أحببت فكرة قاعدة الورقة الواحدة. طبّقتها على مكتب البيت ونجحت فعلاً.', '☘️'),
('سامر','طرطوس','البحر والنعنع والنظام… ثلاثة ما ينفصلوا. موفقية بحياتك ومشوارك.', '🌱'),
('ضيفة','حماة','الموقع مرتب بمزاج النعنع، والرسومات دافئة كأنها من دفتر قديم جميل.', '✨');
